17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        if (hasReachedDailyRegistrationLimit(owner.getRegistrationDate())) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        if (hasReachedCityCapacity(owner.getCity())) {
118	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
119	        }
120	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
121	        owner.setSharesHousehold(sharesHousehold(owner));
122	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
123	        owner.setMembershipTier(determineMembershipTier(owner.getMembershipNumber()));
124	        owner.setCity(normalizeCity(owner.getCity()));
125	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
126	        this.clinicService.saveOwner(owner);
127	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	        headers.setLocation(UriComponentsBuilder.newInstance()
129	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
130	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
131	    }
132	
133	    /**
134	     * The maximum number of owners that may be registered on any single day.
135	     */
136	    private static final long MAX_OWNERS_PER_DAY = 20;
137	
138	    /**
139	     * Determines whether the number of owners already registered on the given date has reached the
140	     * daily registration limit. When 20 owners share the same registration date, no further owner may
141	     * be created for that day.
142	     */
143	    private boolean hasReachedDailyRegistrationLimit(LocalDate registrationDate) {
144	        long ownersRegisteredOnDate = this.clinicService.findAllOwners().stream()
145	            .filter(existing -> Objects.equals(existing.getRegistrationDate(), registrationDate))
146	            .count();
147	        return ownersRegisteredOnDate >= MAX_OWNERS_PER_DAY;
148	    }
149	
150	    /**
151	     * The maximum number of owners that may share a single city.
152	     */
153	    private static final long MAX_OWNERS_PER_CITY = 8;
154	
155	    /**
156	     * Determines whether the given city has already reached its capacity of owners. When a city
157	     * already contains 8 owners, no further owner may be created in that city. Cities are matched
158	     * ignoring letter case.
159	     */
160	    private boolean hasReachedCityCapacity(String city) {
161	        if (city == null) {
162	            return false;
163	        }
164	        long ownersInCity = this.clinicService.findAllOwners().stream()
165	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
166	            .count();
167	        return ownersInCity >= MAX_OWNERS_PER_CITY;
168	    }
169	
170	    /**
171	     * Counts how many existing owners share the given last name at the moment a new owner is
172	     * created. The newly created owner itself is not yet persisted and so is never included in
173	     * the count. Last names are compared exactly.
174	     */
175	    private int countNamesakes(String lastName) {
176	        if (lastName == null) {
177	            return 0;
178	        }
179	        return (int) this.clinicService.findAllOwners().stream()
180	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
181	            .count();
182	    }
183	
184	    /**
185	     * Determines whether the given owner shares a household with an owner that already exists,
186	     * meaning another owner already has the same address and city. Addresses and cities are
187	     * compared ignoring letter case and any surrounding or repeated whitespace. The newly created
188	     * owner itself is not yet persisted and so is never matched against.
189	     */
190	    private boolean sharesHousehold(Owner owner) {
191	        String address = normalize(owner.getAddress());
192	        String city = normalize(owner.getCity());
193	        if (address == null || city == null) {
194	            return false;
195	        }
196	        return this.clinicService.findAllOwners().stream()
197	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
198	                && Objects.equals(normalize(existing.getCity()), city));
199	    }
200	
201	    /**
202	     * The number of owners that receive the founding membership tier. The first 100 owners ever
203	     * created are 'FOUNDING'; every owner created thereafter is 'STANDARD'.
204	     */
205	    private static final int FOUNDING_TIER_LIMIT = 100;
206	
207	    /**
208	     * Determines the membership tier for a newly created owner based on its sequential membership
209	     * number. Owners whose membership number is within the first {@value #FOUNDING_TIER_LIMIT} are
210	     * 'FOUNDING'; all later owners are 'STANDARD'.
211	     */
212	    private String determineMembershipTier(int membershipNumber) {
213	        return membershipNumber <= FOUNDING_TIER_LIMIT ? "FOUNDING" : "STANDARD";
214	    }
215	
216	    /**
217	     * Generates the customer code for a newly created owner. The code is formatted as
218	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
219	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
220	     * Cities are matched ignoring letter case.
221	     */
222	    private String generateCustomerCode(String city) {
223	        long ownersInCity = this.clinicService.findAllOwners().stream()
224	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
225	            .count();
226	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
227	    }
228	
229	    /**
230	     * Normalizes the city of a newly created owner. If an owner already exists in the same
231	     * city (matched ignoring letter case), that existing owner's exact spelling of the city is
232	     * reused so that all owners in a city share one canonical spelling. Otherwise the supplied
233	     * city is title-cased, capitalizing the first letter of each whitespace-separated word and
234	     * lowercasing the rest, so for example "new york" becomes "New York".
235	     */
236	    private String normalizeCity(String city) {
237	        if (city == null) {
238	            return null;
239	        }
240	        return this.clinicService.findAllOwners().stream()
241	            .map(Owner::getCity)
242	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
243	            .findFirst()
244	            .orElseGet(() -> toTitleCase(city));
245	    }
246	
247	    /**
248	     * Title-cases the given value by capitalizing the first letter of each whitespace-separated
249	     * word and lowercasing the remaining letters, preserving the original whitespace: for example
250	     * "new  YORK" becomes "New  York".
251	     */
252	    private static String toTitleCase(String value) {
253	        StringBuilder result = new StringBuilder(value.length());
254	        boolean capitalizeNext = true;
255	        for (int i = 0; i < value.length(); i++) {
256	            char c = value.charAt(i);
257	            if (Character.isWhitespace(c)) {
258	                capitalizeNext = true;
259	                result.append(c);
260	            } else if (capitalizeNext) {
261	                result.append(Character.toTitleCase(c));
262	                capitalizeNext = false;
263	            } else {
264	                result.append(Character.toLowerCase(c));
265	            }
266	        }
267	        return result.toString();
268	    }
269	
270	    /**
271	     * Determines whether an owner already exists that uses the same telephone number
272	     * as the given one. Telephone numbers must be unique across all owners. The
273	     * comparison ignores letter case and any surrounding or repeated whitespace.
274	     */
275	    private boolean isDuplicateOwner(Owner owner) {
276	        String telephone = normalizeTelephone(owner.getTelephone());
277	        return this.clinicService.findAllOwners().stream()
278	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
279	    }
280	
281	    /**
282	     * Normalizes a telephone number for storage and comparison by stripping spaces, dashes
283	     * and parentheses so that only digits remain: for example "(613) 555-0100" becomes
284	     * "6135550100". This lets differently punctuated forms of the same number be treated as
285	     * equal for the uniqueness check and stored in a single canonical form.
286	     */
287	    private static String normalizeTelephone(String telephone) {
288	        if (telephone == null) {
289	            return null;
290	        }
291	        return telephone.replaceAll("[\\s()-]", "");
292	    }
293	
294	    /**
295	     * Determines whether another owner already uses the same email address as the given one.
296	     * Email addresses, when supplied, must be unique across all owners. An owner without an
297	     * email address is never considered a duplicate. The comparison ignores letter case and
298	     * any surrounding or repeated whitespace.
299	     */
300	    private boolean isDuplicateEmail(Owner owner) {
301	        String email = normalize(owner.getEmail());
302	        if (email == null || email.isEmpty()) {
303	            return false;
304	        }
305	        return this.clinicService.findAllOwners().stream()
306	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
307	    }
308	
309	    /**
310	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
311	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
312	     * and "John Smith" normalize to the same key and so count as the same person.
313	     */
314	    private static String normalize(String value) {
315	        if (value == null) {
316	            return null;
317	        }
318	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
319	    }
320	
321	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
322	    @Override
323	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
324	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
325	        if (currentOwner == null) {
326	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
327	        }
328	        currentOwner.setAddress(ownerFieldsDto.getAddress());
329	        currentOwner.setCity(ownerFieldsDto.getCity());
330	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
331	        currentOwner.setLastName(ownerFieldsDto.getLastName());
332	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
333	        this.clinicService.saveOwner(currentOwner);
334	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
335	    }
336	
337	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
338	    @Transactional
339	    @Override
340	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
341	        Owner owner = this.clinicService.findOwnerById(ownerId);
342	        if (owner == null) {
343	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
344	        }
345	        this.clinicService.deleteOwner(owner);
346	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
347	    }
348	
349	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
350	    @Override
351	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
352	        Owner owner = this.clinicService.findOwnerById(ownerId);
353	        if (owner == null) {
354	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
355	        }
356	        HttpHeaders headers = new HttpHeaders();
357	        Pet pet = petMapper.toPet(petFieldsDto);
358	        owner.setId(ownerId);
359	        pet.setOwner(owner);
360	        pet.getType().setName(null);
361	        this.clinicService.savePet(pet);
362	        PetDto petDto = petMapper.toPetDto(pet);
363	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
364	            .buildAndExpand(pet.getId()).toUri());
365	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
366	    }
367	
368	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
369	    @Override
370	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
371	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
372	        if (currentOwner != null) {
373	            Pet currentPet = this.clinicService.findPetById(petId);
374	            if (currentPet != null) {
375	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
376	                currentPet.setName(petFieldsDto.getName());
377	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
378	                this.clinicService.savePet(currentPet);
379	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
380	            }
381	        }
382	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
383	    }
384	
385	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
386	    @Override
387	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
388	        HttpHeaders headers = new HttpHeaders();
389	        Visit visit = visitMapper.toVisit(visitFieldsDto);
390	        Pet pet = new Pet();
391	        pet.setId(petId);
392	        visit.setPet(pet);
393	        this.clinicService.saveVisit(visit);
394	        VisitDto visitDto = visitMapper.toVisitDto(visit);
395	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
396	            .buildAndExpand(visit.getId()).toUri());
397	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
398	    }
399	
400	
401	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
402	    @Override
403	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
404	        Owner owner = this.clinicService.findOwnerById(ownerId);
405	        if (owner != null) {
406	            Pet pet = owner.getPet(petId);
407	            if (pet != null) {
408	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
409	            }
410	        }
411	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
412	    }
413	}
